def group_states(grid):
    # Define the goal position
    goal = 47

    # Initialize a dictionary to store the manhattan distance of each cell from the goal
    distances = {}

    # Calculate the manhattan distance of each cell from the goal
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell == "X":
                continue
            distances[cell] = abs(i - (goal // len(row))) + abs(j - (goal % len(row)))

    # Group states based on their manhattan distance from the goal
    groups = {}
    for state, distance in distances.items():
        if distance not in groups:
            groups[distance] = [state]
        else:
            groups[distance].append(state)

    # Convert the dictionary to a list of lists and return it
    return [list(group) for group in groups.values()]

